{"path":"verify_cube.js","content":"'use strict';
/* Headless verification harness for the Gouraud cube page.
 * Stubs the DOM/canvas, evals the inline page script, unit-tests the
 * rasterizer, then simulates frames and checks pipeline invariants.
 */
const fs = require('fs');
const vm = require('vm');
const path = 'effect_gouraud_shaded_cube_zai-glm-5.3-flash_01.html';

let failures = 0;
function check(name, cond, info) {
  if (cond) console.log('PASS ' + name);
  else { failures++; console.log('FAIL ' + name + (info ? ' — ' + info : '')); }
}

const html = fs.readFileSync(path, 'utf8');
const m = html.match(/<script[^>]*>([\s\S]*?)<\/script>/);
check('script block found', !!m);

let putCount = 0, lastImg = null, texts = [];
const ctx = {
  fillStyle: '', strokeStyle: '', lineWidth: 1, font: '', globalAlpha: 1, lineCap: '', lineJoin: '',
  fillRect() {}, beginPath() {}, moveTo() {}, lineTo() {}, closePath() {}, stroke() {},
  arc() {}, fill() {}, save() {}, restore() {},
  fillText(t) { texts.push(String(t)); },
  createRadialGradient() { return { addColorStop() {} }; },
  createImageData(w, h) { return { width: w, height: h, data: new Uint8ClampedArray(w * h * 4) }; },
  putImageData(img) { putCount++; lastImg = img; }
};
const canvas = { width: 0, height: 0, style: {}, clientWidth: 640, clientHeight: 480,
  getContext: () => ctx, addEventListener() {} };
const listeners = {};
const addL = (t, f) => { (listeners[t] = listeners[t] || []).push(f); };
global.document = { getElementById: () => canvas, addEventListener: addL };
global.window = global;
global.innerWidth = 1280; global.innerHeight = 720; global.devicePixelRatio = 1;
global.performance = { now: () => Date.now() };
global.__CUBE_NO_AUTOSTART = true;
global.addEventListener = addL;

if (m) vm.runInThisContext(m[1], { filename: 'cube-inline.js' });

const app = global.__cubeApp;
check('test API exported', !!app && typeof app.frame === 'function' && typeof app.rasterTriangle === 'function');

// --- resize / canvas sizing
app.resize();
check('resize sized canvas', canvas.width === 640 && canvas.height === 480, canvas.width + 'x' + canvas.height);

// --- rotation matrix preserves lengths
const R = app.buildRotationYX(0.7, 1.3);
const rv = app.transformPoint(R, { x: 0.3, y: 0.7, z: 1.1 });
const len = Math.hypot(rv.x, rv.y, rv.z);
check('rotation preserves length', Math.abs(len - Math.hypot(0.3, 0.7, 1.1)) < 1e-9, 'len=' + len);

// --- rasterTriangle: Gouraud interpolation correctness
const img = ctx.createImageData(48, 48);
const X0 = 2, Y0 = 40, X1 = 24, Y1 = 6, X2 = 44, Y2 = 40;
app.rasterTriangle(img, 48, 48, X0, Y0, X1, Y1, X2, Y2, 1, 0, 0, 255, 64, 64);
const px = (x, y) => { const i = (y * 48 + x) * 4; return [img.data[i], img.data[i + 1], img.data[i + 2], img.data[i + 3]]; };
function expected(x, y) { // barycentric weight of v0 == intensity at (x,y)
  const d = (Y1 - Y2) * (X0 - X2) + (X2 - X1) * (Y0 - Y2);
  return ((Y1 - Y2) * (x - X2) + (X2 - X1) * (y - Y2)) / d;
}
function near(x, y) { // max red among lit pixels in a 7x7 window
  let best = -1;
  for (let dy = -3; dy <= 3; dy++) for (let dx = -3; dx <= 3; dx++) {
    const r = px(x + dx, y + dy);
    if (r[3] === 255 && r[0] > best) best = r[0];
  }
  return best;
}
const nearV0 = near(4, 36);   // near v0, intensity ~1
const darkSpot = near(34, 36); // interior far from v0, intensity ~0.18
const center = near(23, 27);  // interior, expected ~0.32
const expCenter = expected(23, 27);
check('vertex 0 is bright (i=1)', nearV0 > 190, 'r=' + nearV0);
check('interior far from v0 is dark', darkSpot >= 0 && darkSpot < 80, 'r=' + darkSpot);
check('interior intensity interpolates linearly', Math.abs(center / 255 - expCenter) < 0.08, `r=${center} expected~${Math.round(expCenter * 255)}`);
check('outside stays untouched', px(46, 2)[3] === 0, 'alpha=' + px(46, 2)[3]);

// --- simulate 4 seconds of animation
const before = putCount;
let minTri = 99, maxTri = 0, allFacing = true, intensityOk = true;
for (let f = 0; f < 240; f++) {
  app.frame(1 / 60);
  const vis = app.state.lastVisible || [];
  minTri = Math.min(minTri, vis.length); maxTri = Math.max(maxTri, vis.length);
  for (const t of vis) {
    if (t.nx * t.cx + t.ny * t.cy + t.nz * t.cz >= 0) allFacing = false;
    for (const i of t.i) if (!(i >= 0 && i <= 1)) intensityOk = false;
  }
}
check('rendered 240 frames without error', true);
check('putImageData every frame', putCount - before >= 240, (putCount - before) + ' puts');
check('visible triangle count 1..6', minTri >= 1 && maxTri <= 6, `min=${minTri} max=${maxTri}`);
check('all rendered tris face the camera (backface culling ok)', allFacing);
check('intensities within [0,1]', intensityOk);

// cube actually covers a solid screen area
let lit = 0;
for (let i = 3; i < lastImg.data.length; i += 4) if (lastImg.data[i] === 255) lit++;
check('cube rasterizes a solid area', lit > 20000, lit + ' px lit');

// --- HUD / FPS text
const hud = texts.join(' | ');
check('FPS text drawn', /FPS\s*\d/.test(hud), hud.slice(0, 140));

// --- key toggles
const key = k => (listeners.keydown || []).forEach(f => f({ key: k, preventDefault() {} }));
key('w');
check('W enables wireframe', app.state.wireframe === true);
app.frame(1 / 60);
key('w');
check('W disables wireframe', app.state.wireframe === false);
key('p');
check('P pauses', app.state.paused === true);
const tAt = app.state.t;
app.frame(1 / 60); app.frame(1 / 60);
check('paused freezes animation time', app.state.t === tAt);
key('p');
check('P resumes', app.state.paused === false);
check('time advances after resume', app.state.t > tAt);

// --- moving light actually moves
const l1 = { ...app.state.lightPos };
for (let f = 0; f < 120; f++) app.frame(1 / 60);
const l2 = app.state.lightPos;
const moved = Math.hypot(l2.x - l1.x, l2.y - l1.y, l2.z - l1.z);
check('light source moves over time', moved > 0.1, 'moved=' + moved.toFixed(3));

console.log(failures === 0 ? '\nALL TESTS PASSED' : `\n${failures} TEST(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);
"}

